import 'package:flutter/cupertino.dart';
import '../core/load_state.dart';
import '../models/water_model.dart';
import '../services/analytics_service.dart';
import '../services/google_sheets_service.dart';
import '../services/notification_service.dart';
import '../widgets/app_footer.dart';
import '../widgets/common_widgets.dart';

class WaterScreen extends StatefulWidget { const WaterScreen({super.key, required this.service}); final GoogleSheetsService service; @override State<WaterScreen> createState()=>_WaterScreenState(); }
class _WaterScreenState extends State<WaterScreen>{ LoadState<List<WaterModel>> state=LoadState.loading(); String? selected;
 @override void initState(){super.initState(); AnalyticsService.instance.viewWaterSchedule(); _load();}
 Future<void> _load() async { final saved=await widget.service.getSavedNeighborhood(); final r=await widget.service.fetchWater(); if(!mounted)return; setState((){state=r; final data=r.data; if(data!=null&&data.isNotEmpty){selected=data.any((e)=>e.neighborhood==saved)?saved:data.first.neighborhood;}}); }
 Future<void> _pick(List<WaterModel> items) async { var temp=selected ?? items.first.neighborhood; await showCupertinoModalPopup<void>(context: context,builder:(ctx)=>Container(height:300,color:CupertinoColors.systemBackground.resolveFrom(ctx),child:SafeArea(top:false,child:Column(children:[Expanded(child:CupertinoPicker(itemExtent:42,scrollController:FixedExtentScrollController(initialItem:items.indexWhere((e)=>e.neighborhood==temp).clamp(0,items.length-1)),onSelectedItemChanged:(i)=>temp=items[i].neighborhood,children:items.map((e)=>Center(child:Text(e.neighborhood))).toList())),CupertinoButton(child:const Text('تم'),onPressed:(){setState(()=>selected=temp);widget.service.saveNeighborhood(temp);Navigator.pop(ctx);})])))); }
 @override Widget build(BuildContext context)=>CupertinoPageScaffold(navigationBar:const CupertinoNavigationBar(middle:Text('أدوار المياه')),child:SafeArea(child:StateView(state:state,onRetry:_load,builder:(items,cached){final current=items.firstWhere((e)=>e.neighborhood==selected,orElse:()=>items.first);return ListView(padding:const EdgeInsets.all(16),children:[CachedBanner(visible:cached),GlassCard(child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Text('الحي المختار',style:TextStyle(fontWeight:FontWeight.w700)),const SizedBox(height:8),CupertinoButton.tinted(onPressed:()=>_pick(items),child:Text(current.neighborhood)),const SizedBox(height:18),_row(context,'الدور الحالي',current.currentStatus),const SizedBox(height:12),_row(context,'الدور القادم',current.nextStatus),const SizedBox(height:16),if(current.nextArrivalAt!=null) CupertinoButton.filled(onPressed:() async {final ok=await NotificationService.instance.scheduleWaterReminder(neighborhood:current.neighborhood,arrivalAt:current.nextArrivalAt!);if(context.mounted)showCupertinoDialog(context:context,builder:(c)=>CupertinoAlertDialog(title:Text(ok?'تمت الجدولة':'تعذر الجدولة'),content:Text(ok?'سيصل التنبيه قبل الموعد بـ 8 ساعات.':'الموعد قريب أو مضى.'),actions:[CupertinoDialogAction(onPressed:()=>Navigator.pop(c),child:const Text('حسناً'))]));},child:const Text('تفعيل تنبيه قبل 8 ساعات')) else Text('لتفعيل التنبيه الدقيق أضف عمود next_arrival_at بصيغة ISO-8601 إلى جدول المياه.',style:TextStyle(fontSize:13,color:CupertinoColors.secondaryLabel.resolveFrom(context))) ])),const AppFooter()];})));
 Widget _row(BuildContext c,String a,String b)=>Container(padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:CupertinoColors.tertiarySystemBackground.resolveFrom(c),borderRadius:BorderRadius.circular(14)),child:Row(children:[Expanded(child:Text(a)),Expanded(child:Text(b.isEmpty?'غير متوفر':b,textAlign:TextAlign.end,style:const TextStyle(fontWeight:FontWeight.w700)))])); }
